tools.inputSchema:
z.object({
      document,
      address: optionalAddress,
      detail: analysisDetailSchema,
    })

z.object({
      document,
      address: optionalAddress,
      detail: analysisDetailSchema,
    })

z
      .strictObject({
        ...bytePatternFields,
        document,
        start: address.optional(),
        end: address.optional(),
        limit: z.number().int().min(1).max(1000).default(100),
        cursor: z.string().min(1).optional(),
      })
      .superRefine(validateBytePattern)

z.object({
      detail: analysisDetailSchema
        .unwrap()
        .optional()
        .describe(
          "Omitted or complete returns the complete inspection Evidence. summary retains that complete Evidence in this session and returns its inspect_analysis_view summary; use normalized_result.parent_evidence_id for macho pages.",
        ),
    })

z.strictObject({
      inferior_tty: localPathStringSchema
        .optional()
        .describe(
          "Caller-selected terminal path for future inferior runs. GDB must report the exact configured path before the session is ready.",
        ),
    })

z.strictObject({
      session_id: sessionId,
      command: z.string().min(1),
      detail: commandEvidenceDetailSchema,
    })

z.strictObject({
      path: localPathStringSchema,
      inferior_tty: localPathStringSchema,
      backend: z.string().min(1).optional(),
    })

z.strictObject({
      session_id: sessionId,
      command: z
        .string()
        .min(1)
        .refine(
          (value) => !/[\r\n]/u.test(value),
          "A single command line is required",
        ),
    })

tools.outputSchema:
z.strictObject({
      devices: z.array(
        z.strictObject({
          device_id: z.string(),
          name: z.string(),
          type: z.string(),
        }),
      ),
      cleanup_error: z.string().nullable(),
    })

z.strictObject({
      device_id: z.string(),
      processes: z.array(
        z.strictObject({
          pid: z.number().int().nonnegative(),
          name: z.string(),
          identifier: z.string().nullable(),
        }),
      ),
      cleanup_error: z.string().nullable(),
    })

evidenceResultOf(
      fridaSessionStatusSchema.extend({
        source_kind: z.enum(["inline", "file"]),
        source_path: z.string().nullable(),
        source_sha256: z.string().regex(/^[a-f0-9]{64}$/u),
        cleanup_error: z.string().nullable(),
      }),
    )
